import {ARENAS,hero,synergy} from './engine.mjs?v=2';
export function arenaMarkup(game,battle,playing,speed,lastEvent,resultVisible,{icon,esc,portrait}){
 const a=ARENAS.find(a=>a.id===game.arena);
 const total=side=>battle?battle.fighters[side].reduce((n,f)=>n+f.hp,0):0;
 const max=side=>battle?battle.fighters[side].reduce((n,f)=>n+f.maxHp,0):1;
 return `<main><section class="intro arena-intro"><div><div class="eyebrow"><span class="tiny-square"></span> SON SÖZ ARENANIN</div><h1>İki takım.<br><em>Tek kazanan.</em></h1><p>${battle?'Sahada her hamlenin bir karşılığı var.':'Savaş alanını seç. Şansı ayarla. Mücadeleyi başlat.'}</p></div><div class="match-meta"><span class="session-tag">${battle?`TUR ${String(battle.round).padStart(2,'0')}`:'TAKIMLAR HAZIR'}</span><button class="text-button" data-action="setup">${icon('refresh')} Yeni oyun</button></div></section>
 ${!battle?`<div class="arena-config"><div><span class="eyebrow">SAVAŞ ALANI</span><div class="arena-options">${ARENAS.map(x=>`<button data-action="map" data-id="${x.id}" class="arena-option ${game.arena===x.id?'selected':''}"><span class="map-icon map-${x.id}">${icon(x.id==='city'?'bolt':x.id==='asgard'?'star':'shield')}</span><b>${x.name}</b><span>${x.desc}</span>${game.arena===x.id?icon('check'):''}</button>`).join('')}</div></div><div class="luck-setting"><label for="luck">Şans faktörü <strong id="luck-value">%${game.luck}</strong></label><input id="luck" type="range" min="0" max="25" value="${game.luck}"><p>Kritik vuruş olasılığı ve hasar sapması.<br>%0: sabit hasar; hızdan gelen kaçış devam eder.</p><button class="primary" data-action="start">Mücadeleyi başlat ${icon('play')}</button></div></div>`:''}
 <section class="cinema-arena map-${a.id}" aria-label="${a.name} üç boyutlu savaş alanı">
 <div class="arena-scene" id="arena-scene" role="img" aria-label="Kahramanların hareket ettiği 3B ${a.name} arenası"></div><div class="cinema-vignette"></div>
 <div class="cinema-top"><span><span class="live-dot"></span>${a.label}</span><span>${battle?battle.done?'MÜCADELE BİTTİ':playing?'CANLI MÜCADELE':'DURAKLATILDI':'MÜCADELEYE HAZIR'}</span></div>
 <div class="cinema-score"><div class="p0"><span>OYUNCU 01 · UYUM +%${synergy(game.players[0].team)}</span><h2>${esc(game.players[0].name)}</h2><div class="team-health"><i style="width:${battle?total(0)/max(0)*100:100}%"></i></div></div><div class="cinema-vs">VS<small>${battle?'TUR '+battle.round:'ARENA'}</small></div><div class="p1"><span>OYUNCU 02 · UYUM +%${synergy(game.players[1].team)}</span><h2>${esc(game.players[1].name)}</h2><div class="team-health"><i style="width:${battle?total(1)/max(1)*100:100}%"></i></div></div></div>
 <div class="arena-actor-labels" id="arena-actor-labels"></div><div class="arena-hit-label" id="arena-hit-label"></div>
 <div class="action-caption" aria-live="polite">${lastEvent?`<span>${hero(lastEvent.attacker).name} <i>→</i> ${hero(lastEvent.target).name}</span><b>${lastEvent.dodge?'KAÇIŞ':lastEvent.special?lastEvent.skill:lastEvent.crit?'KRİTİK VURUŞ':'SALDIRI'}</b>`:'<span>Takımlar yerlerini aldı</span><b>MÜCADELEYE HAZIR</b>'}</div>
 <div class="arena-camera-controls"><button data-action="camera" data-id="wide" class="${game.camera!=='close'?'active':''}" aria-label="Geniş kamera">GENİŞ</button><button data-action="camera" data-id="close" class="${game.camera==='close'?'active':''}" aria-label="Yakın kamera">YAKIN</button><button data-action="fullscreen" aria-label="Arenayı tam ekran aç" title="Tam ekran">⛶</button></div>
 ${battle?.done&&resultVisible?`<div class="result-overlay"><div class="eyebrow">${battle.decision?'40 TUR · KALAN CAN ORANI':'MÜCADELE TAMAMLANDI'}</div><span class="winner-icon">${icon('star')}</span><h2>${battle.winner===null?'Berabere!':esc(game.players[battle.winner].name)+' kazandı!'}</h2><p>${battle.round} tur · ${battle.events.length} hamle · ${battle.events.filter(e=>e.crit).length} kritik vuruş</p><div><button class="primary" data-action="rematch">Aynı takımlarla rövanş ${icon('refresh')}</button><button class="glass-button" data-action="setup">Yeni oyun</button></div></div>`:''}</section>
 <div class="arena-rosters">${game.players.map((p,side)=>`<div class="arena-roster side-${side}">${p.team.map(id=>{const f=battle?.fighters[side].find(f=>f.id===id),h=hero(id);return `<button class="combat-roster-hero ${f?.hp===0?'eliminated':''} ${lastEvent?.attacker===id?'active':''}" data-action="detail" data-id="${id}" aria-label="${h.name} detayları">${portrait(h)}<div><b>${h.name}</b><span>${f?f.hp===0?'ELENDİ':`${f.hp}/${f.maxHp} CAN${f.shield?' · '+f.shield+' KALKAN':''}`:h.type}</span></div><i class="mini-health"><i style="width:${f?f.hp/f.maxHp*100:100}%"></i></i></button>`;}).join('')}</div>`).join('')}</div>
 ${battle?`<div class="battle-controls"><div><button class="outline" data-action="toggle-play" ${battle.done?'disabled':''}>${icon(playing?'pause':'play')}${playing?'Duraklat':'Devam et'}</button><button class="outline" data-action="step" ${playing||battle.done?'disabled':''}>Tek hamle ${icon('arrow')}</button></div><div class="speed-control"><span>Oynatma hızı</span>${[1,2,4].map(n=>`<button data-action="speed" data-id="${n}" class="${speed===n?'active':''}">${n}×</button>`).join('')}</div></div><section class="battle-log"><div class="section-line"><h2>MÜCADELE GÜNLÜĞÜ</h2><span class="muted">Son ${Math.min(battle.events.length,30)} hamle</span></div><div class="log-entries" aria-live="polite">${battle.events.slice(-30).reverse().map(e=>`<div class="log-entry"><span class="log-round">T${e.round}</span><span class="log-dot p${e.side}"></span><p><b>${hero(e.attacker).name}</b> → ${hero(e.target).name} <strong>${e.dodge?'KAÇIŞ':e.damage+' hasar'}</strong>${e.special?`<span class="log-badge">${e.skill}</span>`:''}${e.crit?'<span class="log-badge critical">KRİTİK</span>':''}${e.knockout?'<span class="log-badge">ELENDİ</span>':''}${e.extras.length?`<small>${e.extras.join(' · ')}</small>`:''}</p></div>`).join('')||'<p class="log-empty">İlk hamle bekleniyor…</p>'}</div></section>`:''}</main>`;
}
